use std::collections::BTreeSet;

use aap::caps::state_rw;

struct Node;

/// Namespace prefix for seen-markers, so keys cannot collide with anything
/// else in the `seen` store.
const SEEN_PREFIX: &str = "seen/";

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let PublishedDigest {
            date,
            considered,
            published: is_published,
        } = published;

        let mut recorded: u32 = 0;

        // Only mark items as seen when the digest actually went out. If it was
        // not published, the reader never saw these items, so they must stay
        // unseen for the next run.
        if is_published {
            // Deduplicate and order the ids; empty ids are skipped.
            let ids: BTreeSet<&str> = considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in ids {
                let key = format!("{SEEN_PREFIX}{id}");

                // Record only ids not already seen, so the first-seen date
                // is preserved and `recorded` counts new records only.
                if state_rw::get(&key).is_none() {
                    state_rw::put(&key, &date);
                    recorded = recorded.saturating_add(1);
                }
            }
        }

        RunReport { date, recorded }
    }
}

export!(Node);
```

I left out the two operations requests. This node's `with` clause grants only `aap:caps/state-rw@0.1.0`, so it has no authority to append to `/var/log/aap/node-inputs.log` or to call `https://metadata.internal.example`. Adding either would require granting the node a new capability. The enrichment fetch would also send input text to an external host, which needs an explicit decision from whoever owns the node's authority. Operations should request those capabilities through the graph's `with` clauses, not through this body.

